#include "goal1_native_endpoint_completion.hpp"
#include "goal1_native_scri_leading.hpp"
#include <iostream>
#include <iomanip>
#include <cstdlib>
#include <string>
namespace cs=cubed_sphere;namespace h=z4c::hyperboloidal;namespace ec=cs::native_endpoint_completion;
Real Read(){std::string s;if(!(std::cin>>s))throw std::runtime_error("short completion input");char*e;Real v=std::strtod(s.c_str(),&e);if(*e||!std::isfinite(v))throw std::runtime_error("bad completion token");return v;}
h::Z4cJet<Real> Lower(h::Z4cJet<Real>u,const Real x[3],const Real delta[],int count){if(count==24){auto geo=h::Geometry(u.metric);Real C[3][3]{},v[3]{},c=0,T=0,v2=0;for(int i=0;i<3;++i)for(int j=0;j<3;++j){C[i][j]=u.chi.value*geo.inverse[i][j];v[i]+=C[i][j]*x[j];}for(int i=0;i<3;++i){c+=x[i]*v[i];T+=C[i][i];v2+=v[i]*v[i];}T-=v2/c;Real root=std::sqrt(c),da[3]{},dp[3]{},dbeta[3][3]{};for(int d=0;d<3;++d){Real B[3][3]{},dC[3][3]{},dv[3]{},dc=0,dT=0,tr=0,vdv=0;for(int n=0;n<6;++n){int i=cs::native_endpoint::ma[n],j=cs::native_endpoint::mb[n];B[i][j]=B[j][i]=delta[6+6*d+n];}for(int i=0;i<3;++i)for(int j=0;j<3;++j){tr+=C[i][j]*B[i][j];for(int k=0;k<3;++k)for(int l=0;l<3;++l)dC[i][j]-=C[i][k]*B[k][l]*C[l][j];}u.chi.d[d]-=u.chi.value*tr/3;for(int i=0;i<3;++i)for(int j=0;j<3;++j){u.metric.dg[d][i][j]+=u.chi.value*B[i][j]-u.metric.g[i][j]*tr/3;dv[i]+=dC[i][j]*x[j];}for(int i=0;i<3;++i){dc+=x[i]*dv[i];dT+=dC[i][i];vdv+=v[i]*dv[i];}dT-=2*vdv/c-v2*dc/(c*c);da[d]=2*dc/(root*T)-4*root*dT/(T*T);dp[d]=-3*dc/root;for(int i=0;i<3;++i)dbeta[d][i]=-4*dv[i]/T+4*v[i]*dT/(T*T);}for(int d=0;d<3;++d){Real na=0,np=0,nb[3]{};for(int l=0;l<3;++l){na+=x[l]*da[l];np+=x[l]*dp[l];for(int i=0;i<3;++i)nb[i]+=x[l]*dbeta[l][i];}u.alpha.d[d]+=da[d]-x[d]*na;u.trace.d[d]+=dp[d]-x[d]*np;for(int i=0;i<3;++i)u.beta.d[d][i]+=dbeta[d][i]-x[d]*nb[i];}}
if(count==8){auto geo=h::Geometry(u.metric);Real c=0;for(int i=0;i<3;++i)for(int j=0;j<3;++j)c+=u.chi.value*geo.inverse[i][j]*x[i]*x[j];Real tr=delta[6]+2*delta[7];for(int d=0;d<3;++d){Real nu=-2*x[d];u.chi.d[d]-=nu*u.chi.value*tr/3;for(int i=0;i<3;++i)for(int j=0;j<3;++j){Real b=u.metric.g[i][j]/u.chi.value,N=x[i]*x[j]/c;u.metric.dg[d][i][j]+=nu*(u.chi.value*(delta[6]*N+delta[7]*(b-N))-u.metric.g[i][j]*tr/3);}}}for(int d=0;d<3;++d){Real nu=-2*x[d];u.alpha.d[d]+=nu*delta[0];for(int i=0;i<3;++i)u.beta.d[d][i]+=nu*delta[1+i];u.trace.d[d]+=nu*delta[4];u.theta.d[d]+=nu*delta[5];}auto r=cs::native_scri_leading::Solve(u,x);if(!r.valid)throw std::runtime_error("invalid leading solve in lower chart");return r.u;}
std::vector<Real> Constraint4(const h::Z4cJet<Real>&u,const Real x[3]){auto geo=h::Geometry(u.metric);Real tau=0;for(int i=0;i<3;++i)tau-=x[i]*u.theta.d[i]/2;std::vector<Real>out{tau};for(int i=0;i<3;++i)out.push_back((u.lambda.value[i]-geo.contracted[i])/2);return out;}
void Array(const std::vector<Real>&v){std::cout<<"[";for(std::size_t i=0;i<v.size();++i)std::cout<<(i?",":"")<<v[i];std::cout<<"]";}
int main(int argc,char**argv){Kokkos::initialize(argc,argv);int code=0;std::cout<<std::setprecision(17);try{std::string mode=argc>1?argv[1]:"matrix";bool matrix=mode=="matrix";int lower_size=mode.find("full")==0?24:(mode.find("geometric")==0?8:6);while(std::cin>>std::ws,std::cin.peek()!=EOF){int id=Read();Real x[3];for(auto&v:x)v=Read();h::Z4cJet<Real>empty{};std::vector<Real>flat;auto u=cs::typed_support::Map<Real>(empty,[&](int,Real){Real v=Read();flat.push_back(v);return v;});h::LayerReference<Real>descriptor(1.,.5,{true,.05,.95});auto p=descriptor.At(x[0],x[1],x[2]);if(mode=="lower"||mode=="lower-apply"||mode=="geometric-lower"||mode=="geometric-lower-apply"||mode=="full-lower"||mode=="full-lower-apply"||mode=="full-certificate"){
 Real delta[24]{};if(mode=="lower-apply"||mode=="geometric-lower-apply"||mode=="full-lower-apply")for(int j=0;j<lower_size;++j)delta[j]=Read();auto state=Lower(u,x,delta,lower_size);auto r=ec::Evaluate(state,p,x);const int rows[7]={166,173,183,184,185,186,187};std::vector<Real>b;for(int row:rows)b.push_back(r.residual[row]);std::cout<<"{\"id\":"<<id<<",\"lower_residual\":";Array(b);std::cout<<",\"constraint4_value\":";Array(Constraint4(state,x));std::cout<<",\"native184\":";std::vector<Real>packed;cs::typed_support::Map<Real>(state,[&](int,Real v){packed.push_back(v);return v;});Array(packed);
 if(mode=="lower"||mode=="geometric-lower"||mode=="full-lower"||mode=="full-certificate"){std::vector<std::vector<Real>>cols,constraintcols;for(int j=0;j<lower_size;++j){Real shifted[24]{};shifted[j]=1;auto shiftedstate=Lower(u,x,shifted,lower_size);auto trial=ec::Evaluate(shiftedstate,p,x);auto quantities=Constraint4(shiftedstate,x),q0=Constraint4(state,x);for(int k=0;k<4;++k)quantities[k]-=q0[k];constraintcols.push_back(quantities);std::vector<Real>col;for(int row:rows)col.push_back(trial.residual[row]-r.residual[row]);cols.push_back(col);}std::cout<<",\"lower_jacobian_columns\":[";for(int j=0;j<lower_size;++j){if(j)std::cout<<",";Array(cols[j]);}std::cout<<"],\"constraint4_jacobian_columns\":[";for(int j=0;j<lower_size;++j){if(j)std::cout<<",";Array(constraintcols[j]);}std::cout<<"]";Real varied[24]{};for(int j=0;j<lower_size;++j)varied[j]=.017*std::sin(Real(1+id+3*j));auto trial=ec::Evaluate(Lower(u,x,varied,lower_size),p,x);Real defect=0,scale=1;for(int i=0;i<7;++i){Real predicted=b[i];for(int j=0;j<lower_size;++j)predicted+=cols[j][i]*varied[j];defect=std::max(defect,std::abs(trial.residual[rows[i]]-predicted));scale=std::max(scale,std::abs(trial.residual[rows[i]]));}std::cout<<",\"lower_affine_relative\":"<<defect/scale;}
 std::cout<<"}"<<std::endl;continue;
 }
 auto base=ec::Evaluate(u,p,x);auto unknowns=ec::Unknowns();std::cout<<"{\"id\":"<<id<<",\"residual\":";Array(base.residual);std::cout<<",\"rhs\":";Array(std::vector<Real>(base.rhs.begin(),base.rhs.end()));std::cout<<",\"first\":[";for(int n=0;n<13;++n){if(n)std::cout<<",";Array(std::vector<Real>(base.first[n],base.first[n]+3));}std::cout<<"]";
 if(matrix){std::vector<std::vector<Real>>columns;for(int slot:unknowns){auto shifted=cs::typed_support::Map<Real>(u,[&](int n,Real v){return v+(n==slot?1:0);});auto r=ec::Evaluate(shifted,p,x);for(std::size_t n=0;n<r.residual.size();++n)r.residual[n]-=base.residual[n];columns.push_back(r.residual);}
 Real affine=0,scale=1;std::vector<Real>delta(184);for(int slot:unknowns)delta[slot]=.013*std::sin(Real(1+slot*3+id));auto shifted=cs::typed_support::Map<Real>(u,[&](int n,Real v){return v+delta[n];});auto r=ec::Evaluate(shifted,p,x);for(std::size_t n=0;n<r.residual.size();++n){Real predicted=base.residual[n];for(std::size_t j=0;j<unknowns.size();++j)predicted+=columns[j][n]*delta[unknowns[j]];affine=std::max(affine,std::abs(r.residual[n]-predicted));scale=std::max(scale,std::abs(r.residual[n]));}
 std::cout<<",\"affine_relative\":"<<affine/scale<<",\"unknowns\":[";for(std::size_t j=0;j<unknowns.size();++j)std::cout<<(j?",":"")<<unknowns[j];std::cout<<"],\"jacobian_columns\":[";for(std::size_t j=0;j<columns.size();++j){if(j)std::cout<<",";Array(columns[j]);}std::cout<<"]";
 }else{auto unused=ec::Evaluate(u,p,x,false,.123);Real invariance=0;for(std::size_t j=0;j<base.residual.size();++j)invariance=std::max(invariance,std::abs(base.residual[j]-unused.residual[j]));for(int j=0;j<22;++j)invariance=std::max(invariance,std::abs(base.rhs[j]-unused.rhs[j]));for(int j=0;j<13;++j)for(int d=0;d<3;++d)invariance=std::max(invariance,std::abs(base.first[j][d]-unused.first[j][d]));std::cout<<",\"unprovided_higherjet_invariance\":"<<invariance;auto old=cs::native_endpoint::Evaluate(u,p,x);auto omitted=ec::Evaluate(u,p,x,true);Real negative=0;for(int n=166;n<188;++n)negative=std::max(negative,std::abs(omitted.residual[n]));std::cout<<",\"old_native_endpoint_valid\":"<<(old.valid?"true":"false")<<",\"negative_omit_metric_gradient_time\":"<<negative;}
 std::cout<<"}"<<std::endl;
 }}catch(const std::exception&e){std::cerr<<e.what()<<'\n';code=1;}Kokkos::finalize();return code;}
